// Adds the permissions and signing config Capacitor's generated project lacks.
//
// mobile/android is generated by `cap add android` on every CI run rather than
// committed, so hand edits cannot live there. This applies them after
// generation instead, which also keeps them reviewable in one place.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const MANIFEST = path.join(ROOT, 'mobile', 'android', 'app', 'src', 'main', 'AndroidManifest.xml');
const GRADLE = path.join(ROOT, 'mobile', 'android', 'app', 'build.gradle');

const PERMISSIONS = `
    <!-- Android 13+ requires the user to grant notifications at runtime. -->
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />
    <!-- Without this, reminders stop after a reboot until the app is opened. -->
    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />
    <!-- Scanning the pairing QR code. -->
    <uses-permission android:name="android.permission.CAMERA" />
`;
// Exact-alarm permissions are deliberately absent. Inexact alarms are correct
// for a study prompt: exact ones need a special-access grant on Android 12+
// and cost noticeably more battery to buy accuracy nobody needs here.

const SIGNING = `
    signingConfigs {
        release {
            if (project.hasProperty('KINVT_KEYSTORE')) {
                storeFile file(project.property('KINVT_KEYSTORE'))
                storePassword project.property('KINVT_KEYSTORE_PASSWORD')
                keyAlias project.property('KINVT_KEY_ALIAS')
                keyPassword project.property('KINVT_KEY_PASSWORD')
            }
        }
    }
    buildTypes {
        release {
            if (project.hasProperty('KINVT_KEYSTORE')) {
                signingConfig signingConfigs.release
            }
            // The UI is plain JavaScript inside a webview, untouched by R8, so
            // shrinking buys nothing and only adds a way for the build to fail.
            minifyEnabled false
        }
    }
`;

let manifest = fs.readFileSync(MANIFEST, 'utf8');
if (!manifest.includes('POST_NOTIFICATIONS')) {
  manifest = manifest.replace('<application', PERMISSIONS + '\n    <application');
  fs.writeFileSync(MANIFEST, manifest);
  console.log('✓ permissions added to AndroidManifest.xml');
} else {
  console.log('✓ permissions already present');
}

let gradle = fs.readFileSync(GRADLE, 'utf8');
if (!gradle.includes('KINVT_KEYSTORE')) {
  gradle = gradle.replace(/android\s*\{/, 'android {\n' + SIGNING);
  fs.writeFileSync(GRADLE, gradle);
  console.log('✓ signing config added to build.gradle');
} else {
  console.log('✓ signing config already present');
}
